import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, seq, id) - max price first, then earliest seq
    sell_heap = []  # (price, seq, id) - min price first, then earliest seq
    book = {}  # id -> [side, price, qty, seq]
    seq_counter = 0

    def add_to_book(side, price, qty, oid, seq):
        book[oid] = [side, price, qty, seq]
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    def peek_valid_top(heap):
        while heap:
            top = heap[0]
            oid = top[2]
            if oid not in book or book[oid][2] <= 0:
                heapq.heappop(heap)
                continue
            return top
        return None

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                del book[oid]
            continue

        oid = order[1]
        side = order[2]
        if typ == 'market':
            price = None
            qty = order[3]
        else:
            price = order[3]
            qty = order[4]

        remaining = qty
        opp_heap = sell_heap if side == 'buy' else buy_heap

        while remaining > 0:
            top = peek_valid_top(opp_heap)
            if top is None:
                break
            opp_id = top[2]
            opp_order = book[opp_id]
            opp_actual_price = opp_order[1]

            if typ != 'market':
                if side == 'buy' and opp_actual_price > price:
                    break
                if side == 'sell' and opp_actual_price < price:
                    break

            trade_qty = min(remaining, opp_order[2])

            if side == 'buy':
                trades.append([oid, opp_id, opp_actual_price, trade_qty])
            else:
                trades.append([opp_id, oid, opp_actual_price, trade_qty])

            remaining -= trade_qty
            opp_order[2] -= trade_qty

            if opp_order[2] <= 0:
                heapq.heappop(opp_heap)
                del book[opp_id]

        if typ == 'limit' and remaining > 0:
            seq_counter += 1
            add_to_book(side, price, remaining, oid, seq_counter)

    return trades

